def is_prime(num):
    # Check for negative numbers, 0, or 1
    if num < 2:
        return False
    # Check for 2 or 3
    elif num == 2 or num == 3:
        return True
    # Check if the number is divisible by 2 or 3
    elif num % 2 == 0 or num % 3 == 0:
        return False
    # Check for all other values of numbers
    else:
        i = 5
        w = 2
        while i*i <= num:
            if num % i == 0:
                return False
            i += w
            w = 6 - w
        return True

